<section class="form-section"><header><h2><?= esc(lang('UI.settingsSmsGateway')) ?></h2></header><form data-settings-config="sms" data-settings-form><div class="settings-channel-fields"><div class="form-field setting-provider"><label for="sms_provider"><?= esc(lang('TenantMisc.smsProvider')) ?></label><select id="sms_provider" name="provider"><option value="" <?= ($sms_config['provider']??'')===''?'selected':'' ?>><?= esc(lang('TenantMisc.selectProvider')) ?></option><option value="unifonic" <?= ($sms_config['provider']??'')==='unifonic'?'selected':'' ?>>Unifonic</option><option value="twilio" <?= ($sms_config['provider']??'')==='twilio'?'selected':'' ?>>Twilio</option><option value="msegat" <?= ($sms_config['provider']??'')==='msegat'?'selected':'' ?>>Msegat</option><option value="custom" <?= ($sms_config['provider']??'')==='custom'?'selected':'' ?>><?= esc(lang('TenantMisc.customApi')) ?></option></select></div><div class="form-field setting-api_key"><label for="sms_api_key"><?= esc(lang('TenantMisc.apiKeyToken')) ?></label><input id="sms_api_key" name="api_key" type="password" autocomplete="new-password"><p><?= esc(lang('TenantMisc.leaveBlankKeepKey')) ?></p></div><div class="form-field setting-sender_id"><label for="sms_sender_id"><?= esc(lang('TenantMisc.senderIdFrom')) ?></label><input id="sms_sender_id" name="sender_id" type="text" value="<?= esc($sms_config['sender_id']??'','attr') ?>"></div><div class="form-field setting-base_url"><label for="sms_base_url"><?= esc(lang('TenantMisc.baseApiUrl')) ?></label><input id="sms_base_url" name="base_url" type="url" value="<?= esc($sms_config['base_url']??'','attr') ?>"></div></div><p class="settings-feedback" role="status" data-settings-feedback></p><footer class="settings-save"><button type="submit" class="button primary" <?= $settingsEdit?'':'disabled' ?>><span><?= esc(lang('UI.settingsSaveGateway')) ?></span></button></footer></form></section>
